                                                                                                                                                                                                                                                                                                                                                                                                        
  CREATE UNIQUE INDEX "TENANT_USER_GROUP_ASSO_EXT_USER_ID_ORG_GROUP_CODE_UINDEX" ON "TENANT_USER_GROUP_ASSO" (CASE "USER_GROUP_CODE" WHEN U'COMMAND_CENTER' THEN SYS_OP_C2C(TO_CHAR("TENANT_ID")||','||TO_CHAR("EXT_USER_ID")||',')||"ORG_GROUP_CODE" WHEN U'DECISION_CENTER' THEN SYS_OP_C2C(TO_CHAR("TENANT_ID")||','||TO_CHAR("EXT_USER_ID")||',')||"ORG_GROUP_CODE" END )     
  ;                                                                                                                                                                                                                                                                                                                                                                                                     

